const std = @import("std");
const linux = std.os.linux;

pub fn main(init: std.process.Init) !void {
    if (!std.mem.eql(u8, @import("builtin").zig_version_string, "0.17.0")) return error.WrongCompiler;
    const args = try init.minimal.args.toSlice(init.arena.allocator());
    if (args.len != 2) return error.ExpectedMode;
    const flags: u32 = if (std.mem.eql(u8, args[1], "ordinary")) 0 else if (std.mem.eql(u8, args[1], "sqpoll")) linux.IORING_SETUP_SQPOLL else return error.UnknownMode;
    var ring = try linux.IoUring.init(64, flags);
    defer ring.deinit();
    if ((ring.features & linux.IORING_FEAT_SUBMIT_STABLE) == 0) return error.SubmitStableFeatureMissing;
    var observations: usize = 0;
    var max_pending: u32 = 0;
    var first: ?struct { batch: usize, returned: u32, pending: u32 } = null;
    var completions: usize = 0;
    for (0..256) |batch| {
        if (ring.sq_ready() != 0 or ring.cq_ready() != 0) return error.PreviousBatchNotRetired;
        for (0..64) |slot| _ = try ring.nop(@intCast(batch * 64 + slot + 1));
        const returned = try ring.submit();
        const pending = ring.sq_ready();
        if (returned > 64 or pending > 64) return error.InvalidSubmissionObservation;
        if (returned > 0 and pending != 0) {
            observations += 1;
            max_pending = @max(max_pending, pending);
            if (first == null) first = .{ .batch = batch, .returned = returned, .pending = pending };
        }
        var seen: [64]bool = @splat(false);
        for (0..64) |_| {
            const cqe = try ring.copy_cqe();
            const base: u64 = @intCast(batch * 64 + 1);
            if (cqe.user_data < base or cqe.user_data >= base + 64 or cqe.res != 0 or cqe.flags != 0) return error.InvalidCompletion;
            const slot: usize = @intCast(cqe.user_data - base);
            if (seen[slot]) return error.DuplicateCompletion;
            seen[slot] = true;
            completions += 1;
        }
        if (ring.sq_ready() != 0 or ring.cq_ready() != 0) return error.BatchNotRetired;
    }
    var storage: [1024]u8 = undefined;
    var stdout = std.Io.File.stdout().writerStreaming(init.io, &storage);
    try stdout.interface.print("{{\"mode\":\"{s}\",\"features\":{d},\"submit_stable\":true,\"batches\":256,\"batch_size\":64,\"completions\":{d},\"pending_observations\":{d},\"max_pending\":{d},\"first\":", .{ args[1], ring.features, completions, observations, max_pending });
    if (first) |value| {
        try stdout.interface.print("{{\"batch\":{d},\"returned\":{d},\"pending\":{d}}}", .{ value.batch, value.returned, value.pending });
    } else try stdout.interface.writeAll("null");
    try stdout.interface.writeAll("}\n");
    try stdout.interface.flush();
}
